/// - Comments: `# This is a comment`
/// - Whitespace around equals: `KEY = value`
/// - Values with equals signs: `URL=https://example.com?foo=bar`
///
/// # Example
///
/// ```
/// use bivvy::config::EnvFileParser;
///
/// let content = r#"
/// # Database config
/// DATABASE_URL=postgres://localhost/db
/// DEBUG="true"
/// EMPTY=
/// "#;
///
/// let vars = EnvFileParser::parse(content).unwrap();
/// assert_eq!(vars.get("DATABASE_URL"), Some(&"postgres://localhost/db".to_string()));
/// assert_eq!(vars.get("DEBUG"), Some(&"true".to_string()));
/// assert_eq!(vars.get("EMPTY"), Some(&"".to_string()));
/// ```
pub struct EnvFileParser;

impl EnvFileParser {
    /// Parse an env file content string into a map of variables.
    pub fn parse(content: &str) -> Result<HashMap<String, String>> {
        let mut vars = HashMap::new();

        for line in content.lines() {
            let line = line.trim();

            // Skip empty lines and comments
            if line.is_empty() || line.starts_with('#') {
                continue;
            }

            // Parse KEY=value
            if let Some((key, value)) = Self::parse_line(line) {
                vars.insert(key, value);
            }
        }

        Ok(vars)
    }

    /// Parse a single line.
    fn parse_line(line: &str) -> Option<(String, String)> {
        let eq_pos = line.find('=')?;
        let key = line[..eq_pos].trim().to_string();
        let value = line[eq_pos + 1..].trim();

        // Handle quoted values
        let value = Self::unquote(value);

        Some((key, value))
    }

    /// Remove surrounding quotes from a value.
    fn unquote(value: &str) -> String {
        if (value.starts_with('"') && value.ends_with('"'))
            || (value.starts_with('\'') && value.ends_with('\''))
        {
            if value.len() >= 2 {
                value[1..value.len() - 1].to_string()
            } else {
                value.to_string()
            }
        } else {
            value.to_string()
        }
    }

    /// Load and parse an env file from a path.
    ///
    /// # Example
    ///
    /// ```no_run
    /// use bivvy::config::EnvFileParser;
    /// use std::path::Path;
    ///
    /// let vars = EnvFileParser::load(Path::new(".env")).unwrap();
    /// for (key, value) in &vars {
    ///     println!("{}={}", key, value);
    /// }
    /// ```
    pub fn load(path: &Path) -> Result<HashMap<String, String>> {
        let content = std::fs::read_to_string(path)?;
        Self::parse(&content)
    }

    /// Load and parse an env file, returning empty map if file doesn't exist.
    pub fn load_optional(path: &Path) -> Result<HashMap<String, String>> {
        if path.exists() {
            Self::load(path)
        } else {
            Ok(HashMap::new())
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_simple_env_file() {
        let content = r#"
KEY1=value1
KEY2=value2
"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("KEY1"), Some(&"value1".to_string()));
        assert_eq!(vars.get("KEY2"), Some(&"value2".to_string()));
    }

    #[test]
    fn skips_comments() {
        let content = r#"
# This is a comment
KEY=value
# Another comment
"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.len(), 1);
        assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
    }

    #[test]
    fn handles_quoted_values() {
        let content = r#"
DOUBLE="double quoted"
SINGLE='single quoted'
UNQUOTED=no quotes
"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("DOUBLE"), Some(&"double quoted".to_string()));
        assert_eq!(vars.get("SINGLE"), Some(&"single quoted".to_string()));
        assert_eq!(vars.get("UNQUOTED"), Some(&"no quotes".to_string()));
    }

    #[test]
    fn handles_empty_values() {
        let content = "EMPTY=";

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("EMPTY"), Some(&"".to_string()));
    }

    #[test]
    fn handles_values_with_equals() {
        let content = "URL=https://example.com?foo=bar";

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(
            vars.get("URL"),
            Some(&"https://example.com?foo=bar".to_string())
        );
    }

    #[test]
    fn handles_whitespace_around_equals() {
        let content = "KEY = value with spaces";

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("KEY"), Some(&"value with spaces".to_string()));
    }

    #[test]
    fn skips_empty_lines() {
        let content = r#"
KEY1=value1

KEY2=value2

"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.len(), 2);
    }

    #[test]
    fn handles_lines_without_equals() {
        let content = r#"
KEY1=value1
invalid line without equals
KEY2=value2
"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.len(), 2);
    }

    #[test]
    fn load_optional_returns_empty_for_missing_file() {
        let result = EnvFileParser::load_optional(Path::new("/nonexistent/path/.env"));

        assert!(result.is_ok());
        assert!(result.unwrap().is_empty());
    }

    #[test]
    fn complex_env_file() {
        let content = r#"
# Application settings
APP_NAME=MyApp
DEBUG=true

# Database
DATABASE_URL="postgres://user:pass@localhost:5432/db"

# API Keys
API_KEY='secret-key-123'
WEBHOOK_URL=https://api.example.com/webhook?token=abc&id=123
"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("APP_NAME"), Some(&"MyApp".to_string()));
        assert_eq!(vars.get("DEBUG"), Some(&"true".to_string()));
        assert_eq!(
            vars.get("DATABASE_URL"),
            Some(&"postgres://user:pass@localhost:5432/db".to_string())
        );
        assert_eq!(vars.get("API_KEY"), Some(&"secret-key-123".to_string()));
        assert!(vars.get("WEBHOOK_URL").unwrap().contains("token=abc"));
    }

    // --- Quote edge cases ---

    #[test]
    fn empty_double_quoted_value() {
        let vars = EnvFileParser::parse(r#"KEY="""#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"".to_string()));
    }

    #[test]
    fn empty_single_quoted_value() {
        let vars = EnvFileParser::parse("KEY=''").unwrap();
        assert_eq!(vars.get("KEY"), Some(&"".to_string()));
    }

    #[test]
    fn mismatched_quotes_double_then_single() {
        // Mismatched quotes are not stripped
        let vars = EnvFileParser::parse(r#"KEY="value'"#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#""value'"#.to_string()));
    }

    #[test]
    fn mismatched_quotes_single_then_double() {
        let vars = EnvFileParser::parse(r#"KEY='value""#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#"'value""#.to_string()));
    }

    #[test]
    fn single_quotes_inside_double_quotes() {
        let vars = EnvFileParser::parse(r#"KEY="it's a test""#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"it's a test".to_string()));
    }

    #[test]
    fn double_quotes_inside_single_quotes() {
        let vars = EnvFileParser::parse(r#"KEY='say "hello"'"#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#"say "hello""#.to_string()));
    }

    #[test]
    fn single_double_quote_char_as_value() {
        // A lone `"` starts and ends with `"` but length is 1 (< 2),
        // so it is returned as-is.
        let vars = EnvFileParser::parse("KEY=\"").unwrap();
        assert_eq!(vars.get("KEY"), Some(&"\"".to_string()));
    }

    #[test]
    fn single_single_quote_char_as_value() {
        let vars = EnvFileParser::parse("KEY='").unwrap();
        assert_eq!(vars.get("KEY"), Some(&"'".to_string()));
    }

    #[test]
    fn quote_in_middle_of_unquoted_value() {
        // Not surrounded by quotes, so no stripping occurs
        let vars = EnvFileParser::parse(r#"KEY=val"ue"#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#"val"ue"#.to_string()));
    }

    #[test]
    fn quoted_value_with_spaces_inside() {
        let vars = EnvFileParser::parse(r#"KEY="  spaced  ""#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"  spaced  ".to_string()));
    }

    // --- Escaped character edge cases ---

    #[test]
    fn backslash_escaped_quotes_not_processed() {
        // The parser does NOT interpret escape sequences — backslashes are literal.
        // The outer quotes are stripped, but inner `\"` remains as-is.
        let vars = EnvFileParser::parse(r#"KEY="value \"nested\"""#).unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&r#"value \"nested\"#.to_string())
        );
    }

    #[test]
    fn literal_backslash_n_in_value() {
        // \n as two literal characters (not a newline) preserved as-is
        let vars = EnvFileParser::parse(r#"KEY="line1\nline2""#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#"line1\nline2"#.to_string()));
    }

    #[test]
    fn literal_backslash_t_in_value() {
        let vars = EnvFileParser::parse(r#"KEY="col1\tcol2""#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#"col1\tcol2"#.to_string()));
    }

    #[test]
    fn backslash_at_end_of_value() {
        let vars = EnvFileParser::parse(r#"KEY=path\to\"#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#"path\to\"#.to_string()));
    }

    #[test]
    fn backslashes_in_unquoted_value() {
        let vars = EnvFileParser::parse(r"KEY=C:\Users\name\file").unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&r"C:\Users\name\file".to_string())
        );
    }

    // --- Key edge cases ---

    #[test]
    fn empty_key_with_value() {
        let vars = EnvFileParser::parse("=value").unwrap();
        assert_eq!(vars.get(""), Some(&"value".to_string()));
    }

    #[test]
    fn key_with_underscores_and_digits() {
        let vars = EnvFileParser::parse("MY_VAR_2=abc").unwrap();
        assert_eq!(vars.get("MY_VAR_2"), Some(&"abc".to_string()));
    }

    #[test]
    fn key_with_lowercase() {
        let vars = EnvFileParser::parse("lower_case=works").unwrap();
        assert_eq!(vars.get("lower_case"), Some(&"works".to_string()));
    }

    // --- Whitespace edge cases ---

    #[test]
    fn leading_and_trailing_whitespace_on_line() {
        let vars = EnvFileParser::parse("   KEY=value   ").unwrap();
        assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
    }

    #[test]
    fn tabs_as_whitespace() {
        let vars = EnvFileParser::parse("\tKEY=value\t").unwrap();
        assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
    }

    #[test]
    fn whitespace_only_lines_are_skipped() {
        let content = "KEY1=a\n   \n\t\nKEY2=b";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.len(), 2);
    }

    #[test]
    fn value_whitespace_is_trimmed_before_unquoting() {
        // Whitespace around the value is trimmed, then quotes are checked
        let vars = EnvFileParser::parse(r#"KEY = "quoted" "#).unwrap();
        // After trim: `"quoted"` — the trailing space is outside the quotes
        // and gets trimmed, so unquote sees `"quoted"` → `quoted`
        assert_eq!(vars.get("KEY"), Some(&"quoted".to_string()));
    }

    // --- Inline comments (not stripped — documented behavior) ---

    #[test]
    fn inline_comments_included_in_value() {
        // The parser does NOT strip inline comments — they become part of the value
        let vars = EnvFileParser::parse("KEY=value # this is not stripped").unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&"value # this is not stripped".to_string())
        );
    }

    #[test]
    fn hash_inside_quoted_value() {
        let vars = EnvFileParser::parse(r#"KEY="value # with hash""#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"value # with hash".to_string()));
    }

    // --- Multiple equals signs ---

    #[test]
    fn multiple_equals_in_value() {
        let vars = EnvFileParser::parse("KEY=a=b=c=d").unwrap();
        assert_eq!(vars.get("KEY"), Some(&"a=b=c=d".to_string()));
    }

    #[test]
    fn base64_value_with_trailing_equals() {
        let vars = EnvFileParser::parse("SECRET=dGVzdA==").unwrap();
        assert_eq!(vars.get("SECRET"), Some(&"dGVzdA==".to_string()));
    }

    // --- Duplicate keys ---

    #[test]
    fn duplicate_key_last_wins() {
        let content = "KEY=first\nKEY=second";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"second".to_string()));
    }

    // --- export prefix (not handled — included in key) ---

    #[test]
    fn export_prefix_included_in_key() {
        // The parser does NOT strip `export ` — it becomes part of the key
        let vars = EnvFileParser::parse("export KEY=value").unwrap();
        assert!(vars.get("KEY").is_none());
        assert_eq!(vars.get("export KEY"), Some(&"value".to_string()));
    }

    // --- File I/O ---

    #[test]
    fn load_reads_file_from_disk() {
        let temp = tempfile::TempDir::new().unwrap();
        let env_path = temp.path().join(".env");
        std::fs::write(&env_path, "FROM_FILE=loaded\nNUM=42").unwrap();

        let vars = EnvFileParser::load(&env_path).unwrap();
        assert_eq!(vars.get("FROM_FILE"), Some(&"loaded".to_string()));
        assert_eq!(vars.get("NUM"), Some(&"42".to_string()));
    }

    #[test]
    fn load_returns_error_for_missing_file() {
        let result = EnvFileParser::load(Path::new("/nonexistent/.env"));
        assert!(result.is_err());
    }

    #[test]
    fn load_optional_reads_existing_file() {
        let temp = tempfile::TempDir::new().unwrap();
        let env_path = temp.path().join(".env");
        std::fs::write(&env_path, "OPT=yes").unwrap();

        let vars = EnvFileParser::load_optional(&env_path).unwrap();
        assert_eq!(vars.get("OPT"), Some(&"yes".to_string()));
    }

    // --- Completely empty input ---

    #[test]
    fn empty_string_returns_empty_map() {
        let vars = EnvFileParser::parse("").unwrap();
        assert!(vars.is_empty());
    }

    #[test]
    fn only_comments_returns_empty_map() {
        let content = "# comment 1\n# comment 2\n";
        let vars = EnvFileParser::parse(content).unwrap();
        assert!(vars.is_empty());
    }

    #[test]
    fn only_blank_lines_returns_empty_map() {
        let vars = EnvFileParser::parse("\n\n\n").unwrap();
        assert!(vars.is_empty());
    }

    // --- Unicode values ---

    #[test]
    fn unicode_in_value() {
        let vars = EnvFileParser::parse("GREETING=こんにちは").unwrap();
        assert_eq!(vars.get("GREETING"), Some(&"こんにちは".to_string()));
    }

    #[test]
    fn unicode_in_quoted_value() {
        let vars = EnvFileParser::parse(r#"MSG="café ☕""#).unwrap();
        assert_eq!(vars.get("MSG"), Some(&"café ☕".to_string()));
    }

    #[test]
    fn emoji_in_value() {
        let vars = EnvFileParser::parse("EMOJI=🚀🎉").unwrap();
        assert_eq!(vars.get("EMOJI"), Some(&"🚀🎉".to_string()));
    }
}
